s.options.length === 0) return null\n\n        return createPortal(\n            <MarkdownFileSearchMenu\n                onHighlight={itemProps.setHighlightedIndex}\n                onSelect={itemProps.selectOptionAndCleanUp}\n                options={itemProps.options}\n                selectedIndex={itemProps.selectedIndex}\n            />,\n            anchorElementRef.current,\n        )\n    }, [])\n\n    return (\n        <LexicalTypeaheadMenuPlugin<MarkdownFileSearchOption>\n            menuRenderFn={renderMenu}\n            onQueryChange={handleQueryChange}\n            onSelectOption={handleSelectOption}\n            options={options}\n            parent={overlayContainer ?? undefined}\n            triggerFn={triggerFn}\n        />\n    )\n}\n\r\n",
design\activity\card__5cdae748-9597-4d29-8dc0-3d4b5df3aa7f.json:6286:          "content": "import { repositoryFileMatchesQuery } from './markdown_file_search'\nimport { MarkdownFileSearchOption } from './markdown_file_search_option'\n\n/** Build file-search options only while a typeahead query is active. */\nexport function createFileSearchOptions(repositoryFiles: readonly string[], query: string | null) {\n    if (query === null) return []\n\n    return repositoryFiles\n        .filter((repositoryPath) => repositoryFileMatchesQuery(repositoryPath, query))\n        .map((repositoryPath) => new MarkdownFileSearchOption(repositoryPath))\n}\n\r\n",
